var palette = [];
var ctx;
var connectionNodes = []; // 描画された図形の端点や縁のポイントを格納

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	background('#ffffff');
	noFill();

	// 外枠の描画
	square(width / 2, height / 2, width * 0.96);
	square(width / 2, height / 2, width * 0.95);

	// 再帰的な矩形分割の開始
	divideRect(width / 2, height / 2, width * 0.95, 5);

	// 格納されたポイントに小さな円を描画
	ctx.setLineDash([0]);
	for (let p of connectionNodes) {
		let d = width * 0.004;
		circle(p.x, p.y, d);
	}

	// ポイント同士をランダムに接続する処理
	let maxLineLength = width * 0.25;
	let connectionAttempts = int(random(1000));
	if (connectionNodes.length > 0) {
		for (let i = 0; i < connectionAttempts; i++) {
			let p1 = random(connectionNodes);
			let p2 = random(connectionNodes);
			var d = dist(p1.x, p1.y, p2.x, p2.y);
			if (d < maxLineLength) {
				applyRandomStyle();
				line(p1.x, p1.y, p2.x, p2.y);
			}
		}
	}
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);


  pop();
}

// 矩形を再帰的に分割する関数
function divideRect(x, y, w, depth) {
	let cellCount = random([1, 2]);
	let cellW = w / cellCount;
	let margin = width * 0.003;

	if (depth > 0) {
		depth--;
		for (let i = 0; i < cellCount; i++) {
			for (let j = 0; j < cellCount; j++) {
				let cellX = i * cellW + x - (w / 2) + (cellW / 2);
				let cellY = j * cellW + y - (w / 2) + (cellW / 2);
				divideRect(cellX, cellY, cellW, depth);
			}
		}
	} else {
		// 分割の最小単位（リーフ）に図形を描画
		generateElements(x, y, w - margin);
	}
}

// 各セルの中に具体的な図形を生成する関数
function generateElements(x, y, w) {
	applyRandomStyle();
	square(x, y, w);

	let edgePointCount = int(random(3));
	let shapeDensity = 7;

	// セルの縁にランダムなポイントを生成
	for (let j = 0; j < edgePointCount; j++) {
		let xx = x + random(-1, 1) * -(w / 2);
		let yy = y + random([-1, 1]) * (w / 2);
		if (random() < 0.5) {
			xx = x + random([-1, 1]) * (w / 2);
			yy = y + random(-1, 1) * -(w / 2);
		}
		connectionNodes.push({ x: xx, y: yy });
	}

	// セル内にランダムな図形（弧、円、線）を描画
	for (let i = 0; i < shapeDensity; i++) {
		let type = int(random(4));
		if (type === 1) {
			drawArcElement(x, y, w, int(random(4)));
		} else if (type === 2) {
			drawCircleElement(x, y, w);
		} else if (type === 3) {
			drawLineElement(x, y, w);
		}
	}
}

function drawArcElement(x, y, w, dir) {
	var d = w * 2;
	let a1 = 0;
	let a2 = PI / 2;
	var xx = x - (w / 2);
	var yy = y - (w / 2);

	if (dir === 1) {
		a1 = PI / 2; a2 = PI;
		xx = x + (w / 2);
	} else if (dir === 2) {
		a1 = PI; a2 = PI * 1.5;
		xx = x + (w / 2); yy = y + (w / 2);
	} else if (dir === 3) {
		a1 = PI * 1.5; a2 = TAU;
		yy = y + (w / 2);
	}
	arc(xx, yy, d, d, a1, a2);

	// 弧の上にポイントを追加
	let n = int(random(4));
	let r = d / 2;
	for (let i = 0; i < n; i++) {
		let a = random(a1, a2);
		connectionNodes.push({ x: xx + r * cos(a), y: yy + r * sin(a) });
	}
}

function drawCircleElement(x, y, w) {
	var d = w * random(0.1, 0.9);
	circle(x, y, d);

	// 円周上にポイントを追加
	var n = int(random(3));
	for (let i = 0; i < n; i++) {
		var a = random(TAU);
		var r = d / 2;
		var xx = x + r * cos(a);
		var yy = y + r * sin(a);
		connectionNodes.push({ x: xx, y: yy });
	}
}

function drawLineElement(x, y, w) {
	var xx = x + w * random(-1, 1) * 0.4;
	var yy = y + w * random(-1, 1) * 0.4;
	line(xx, y - (w / 2), xx, y + (w / 2));
	line(x - (w / 2), yy, x + (w / 2), yy);
	connectionNodes.push({ x: xx, y: yy });
}

// 線の太さや色、破線などのスタイルをランダムに設定する関数
function applyRandomStyle() {
	let thickness = width * random(0.0012, 0.0008);
	let dashPattern = [0];
	let strokeColor = random(['#363636', '#363636', '#363636', '#363636', '#ba0e0e', '#1447ac']);

	if (random() < 0.5) {
		for (let i = 0; i < 5; i++) {
			dashPattern.push(width * random(0.002, 0.005));
		}
	}
	ctx.setLineDash(dashPattern);
	strokeWeight(thickness);
	stroke(strokeColor);
}
